from fastapi.background import BackgroundTasks

def unwrap_annotated(annotation: Any) -> Any:
    """Recursively unwraps Annotated types."""
    if get_origin(annotation) is Annotated:
        # The actual type is the first argument in Annotated
        # We recursively unwrap this type in case it is also Annotated
        return unwrap_annotated(get_args(annotation)[0])
    return annotation
